xql_query:
// ============================================================
// Rule: SLP_Airflow DAG Failure Detected
// Vendor: Airflow
// Objective:
// Detect activity associated with SLP_Airflow DAG Failure Detected.
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.

// Consulta de falhas registradas no Airflow
// Objetivo: listar os principais campos relacionados a falhas de DAGs,
// incluindo data/hora da ocorrência, ambiente, status, tipo da falha,
// detalhe do erro e task impactada.

config case_sensitive = false

// Dataset com os eventos brutos do Airflow
| dataset = airflow_airflow_raw

| filter (dag not in ("""<INTERNAL_DAG_ID_2>""", """<INTERNAL_DAG_ID_1>""")) 
// Seleção dos campos relevantes para análise da falha
| fields
    _insert_time,                         // Data/hora de ingestão do evento no XSIAM
    data_e_hora_da_ocorrencia_da_falha,   // Data/hora em que a falha ocorreu no Airflow
    dag,                                  // Nome da DAG impactada
    Status,                               // Status da execução ou da falha
    Ambiente,                             // Ambiente onde ocorreu a falha, ex: Produção, Homologação, Desenvolvimento
    Tipo_de_falha,                        // Classificação ou tipo da falha identificada
    Detalhe_do_erro_ocorrido,             // Mensagem ou detalhe técnico do erro
    Task_que_ocorreu_a_falha              // Task específica da DAG onde a falha ocorreu
